def valid_date(date):
    import re
    if not date:
        return False
    if not re.fullmatch(r'\d{2}-\d{2}-\d{4}', date):
        return False
    mm, dd, yyyy = map(int, date.split('-'))
    if mm < 1 or mm > 12:
        return False
    if dd < 1:
        return False
    if mm in (1, 3, 5, 7, 8, 10, 12):
        return dd <= 31
    if mm in (4, 6, 9, 11):
        return dd <= 30
    if mm == 2:
        if yyyy % 400 == 0 or (yyyy % 4 == 0 and yyyy % 100 != 0):
            return dd <= 29
        else:
            return dd <= 28
    return False
